import type { Detail } from "./detail.en";

export const detailUz: Record<string, Detail> = {
  "2": [["O'ng tomonlama harakat O'zbekistonning barcha umumiy foydalanishdagi yo'llarida amal qiladi.", "Quvib o'tish, burilish, to'xtab turish va sekin harakatlanuvchilar qoidalari o'ng tomonda yurishingizni nazarda tutadi.", "Belgilar va ustuvorliklar shu asosiy qoida ustiga Vena konventsiyasi ruhida quriladi."], "Istalgan yo'lga chiqqanda siz o'z yo'nalishingizdagi o'ng tasmani egallaysiz, chap tomonni emas."],
  "3": [["Faqat Qoidalar matni emas, signallar, belgilar va chiziqlar ham majburiy.", "Tartibga soluvchilar: militsiya, harbiy avtomobil nazorati, xizmat vazifasidagi yo'l xizmati xodimlari, temir yo'l kesishmasi va sol kechuvi navbatchilari hamda jamoatchilik vakillari.", "Tartibga soluvchi ko'rinib turishi kerak: maxsus kiyim yoki belgi, masalan qo'l bog'ichi, jezl, qizil qaytargich, chiroq yoki bayroqcha."], "Svetofor buzilgan chorrahada formadagi xodim qizil chiroqda o'tishga ishora qiladi: siz svetoforga emas, xodimga amal qilasiz."],
  "4": [["Yo'l qoplamasini buzish, o'zgartirish, belgi va svetoforlarni olib tashlash, to'sish va shikastlash taqiqlanadi.", "Yo'lda narsa qoldirish, ruxsatsiz to'siq qo'yish va sun'iy notekislik o'rnatish mumkin emas.", "To'siq yaratsangiz, uni tezda bartaraf eting, barcha vosita bilan ogohlantiring va IIOga xabar bering."], "Yuk tasmaga tushdi: avariya chiroqlarini yoqing, belgi qo'ying va darhol olib tashlay olmasangiz xabar bering."],
  "d-yield": [["Yo'l berish — kutish majburiyati, iltifot emas.", "Harakatingiz imtiyozli ishtirokchini tormozlash yoki burilishga majbur qilsa, doim amal qiladi.", "Imtiyoz — o'z yo'nalishida birinchi o'tish huquqi."], "Yo'l bering chizig'ida siz uzoqdagi mashinani ham kutasiz, agar u sizdan ko'ra tormozlashga majbur bo'lsa."],
  "d-main": [["Qattiq qoplamali (asfalt, beton) yo'l tuproqli yoki shag'alli yo'lga nisbatan asosiy.", "Ustuvorlik belgisi chorrahada yo'lni asosiy qilishi mumkin.", "Yondosh hududdan chiqadigan yo'lga nisbatan har qanday yo'l asosiy."], "Asfaltli ko'cha shag'alli yo'l bilan kesishadi: asfaltli asosiy, shag'alli yo'l beradi."],
  "d-stop": [["To'xtash 10 daqiqagacha, to'xtab turish undan uzoq.", "Yo'lovchi chiqarish va tushirish, yuk ortish va tushirish qisqa vaqt — to'xtash hisoblanadi.", "Ba'zi taqiqlar to'xtashni, boshqalari faqat to'xtab turishni taqiqlaydi, shuning uchun har birini o'qing."], "Yo'lovchini ikki daqiqaga tushirish — to'xtash. Mashinani bir soatga qoldirish — to'xtab turish."],
  "d-vis": [["Yetarlicha ko'rinmaslik — oldinda 300 m dan kam ko'rinish.", "Yomg'ir, qor, tuman va g'ira-shira vaqtda bo'ladi.", "Chiroqlar va tumanga qarshi faralar qoidalari shunga bog'liq."], "Zich tumanda 80 m ko'rinishda yaqin nurni yoqasiz va tumanga qarshi farani qo'shishingiz mumkin."],

  "7": [["Tegishli toifadagi guvohnoma, ro'yxatdan o'tish guvohnomasi va sug'urta polisi (elektron ham bo'ladi) yoningizda bo'lsin.", "Xorijiy transportga qo'shimcha hujjatlar, masalan qaytarib olib chiqish majburiyatnomasi kerak.", "Biometrik pasport yoki ID-karta bo'lsa, ko'p hujjatlar elektron tekshiriladi."], "Sizni to'xtatishdi: guvohnoma va ro'yxatdan o'tish guvohnomasini ko'rsatasiz, polis telefonda bo'lishi mumkin."],
  "8": [["«A» mototsikllar, «A1» moped, skuter va kichik hajmdagi mototransportni qamrab oladi.", "«B» 3 500 kg gacha va sakkiztagacha yo'lovchi o'rindig'i, «C» og'irroq yuk mashinalari, «D» sakkiztadan ortiq yo'lovchi o'rindig'i.", "«BE», «CE» va «DE» 750 kg dan og'ir tirkamani qo'shadi."], "Sakkiz yo'lovchi o'rindig'i bor mikroavtobusni «B» bilan haydash mumkin. To'qqiz o'rindiqqa «D» kerak."],
  "9": [["Harakatdan oldin kamarni taqing. Bu haydovchi va old o'rindiqdagilarga tegishli.", "Istisnolar: orqa o'rindiqdagi 12 yoshgacha bolalar, o'quv mashinasidagi instruktor, homilador ayollar va ma'lumotnomali bemorlar, maxsus transport.", "Mototsikl, moped va skuterda haydovchi va yo'lovchi motoshlemni qadab oladi."], "Old o'rindiqdagi yo'lovchi kamarini taqmagan: u taqmaguncha yurmaysiz."],
  "11": [["Yo'lga chiqishdan oldin texnik holat, tozalik va jihozlanishni tekshiring.", "Harakatdan oldin yo'lovchilar joylashgan, eshiklar yopiq bo'lsin. Ularni chiqmaslik va kamar taqishga ogohlantiring.", "Qorong'ida majburiy to'xtagach, qatnov qismiga chiqishdan oldin nur qaytargichli jilet kiying."], "Mashina kechasi buzildi: avval jiletni kiyasiz, keyin ko'rgani chiqasiz."],
  "12": [["Mast holatda, giyohvand moddalar, uyqu keltiruvchi dorilar, xavfli charchoq yoki betoblikda boshqarish taqiqlanadi.", "Mashinani mast yoki guvohnomasiz shaxsga bermang.", "Nosoz tormoz yoki rul, qorong'ida yonmaydigan chiroqlar, yomg'ir va qorda ishlamaydigan tozalagich ham haydashni taqiqlaydi."], "Guvohnomasiz do'stingiz sokin ko'chada sinab ko'rmoqchi. Siz rad etishingiz shart."],
  "12p": [["Telefondan faqat qo'llarni ishlatmasdan foydalaning.", "Salon oldidagi ekranda tele va videomahsulotlarni ko'rish taqiqlanadi.", "Ruxsatsiz sirena va ratsiya o'rnatish, aholi punktida baland musiqa va dvigatel shovqini taqiqlanadi."], "Qo'ng'iroq: qo'llarsiz aloqadan foydalanasiz yoki javob bermaysiz. Telefonni hech qachon qo'lda ushlamaysiz."],

  "13": [["Darhol to'xtang, avariya chiroqlarini yoqing va belgini qo'ying. Transport va narsalarni hozircha qo'zg'atmang.", "Birinchi yordam ko'rsating, tez yordam va qutqaruvchilarni chaqiring, IIOga xabar bering.", "Harakatga xalaqit bersangiz, avval joylashuvni foto, video yoki guvohlar bilan qayd eting, keyin qatnov qismini bo'shating."], "Yengil to'qnashuv tasmani to'sdi: mashinalarni suratga olasiz, chetga olasiz va IIOni kutasiz."],

  "15": [["Trotuar, piyodalar yoki birgalikdagi yo'lkalardan yuring. Ular bo'lmasa yo'l yoqasidan.", "Qatnov qismi chetida transportga qarshi yuring, mashinalarni ko'rasiz.", "Velosiped, moped, aravacha yoki elektrosamokatni yetaklaganlar transport yo'nalishi bo'ylab yuradi."], "Qishloq yo'lida mashinalarga yuzma-yuz yurasiz, lekin velosipedingizni transport yo'nalishida yetaklaysiz."],
  "16": [["Bir qatorda to'rtdan ko'p emas, o'ng tomonda, transport yo'nalishida.", "Qizil bayroqchali kuzatuvchi old va orqada chap tomonda yuradi. Qorong'ida oldida oq, orqasida qizil chiroq.", "Bolalar guruhi trotuarlardan, yo'l yoqasidan faqat kunduzi va kattalar bilan."], "O'n kishilik maktab guruhi qishloq yo'lida to'rttalab saf tortib, old va orqada kattalar bilan yuradi."],
  "17": [["Piyodalar o'tish joylari, yer osti va yer usti o'tish joylaridan kesib o'ting.", "Ular bo'lmasa, chorrahada trotuar chizig'i bo'ylab yoki yo'l ikki tomonga ko'rinadigan joydan to'g'ri burchak ostida.", "Ajratuvchi mintaqa yoki to'siq bor yo'llarda faqat belgilangan joyda."], "Yo'l o'rtasida to'siq bor: siz oshib o'tmay, o'tish joyiga borasiz."],
  "18": [["Avval piyodalar svetofori, u bo'lmasa transport svetofori.", "Tartibga soluvchi ishoralari svetofordan ustun.", "Yashil ruxsat beradi, qizil taqiqlaydi."], "Chorrahada piyodalar svetofori yo'q: sizga qaragan transport svetoforiga amal qilasiz."],
  "19": [["Tartibga solinmagan o'tish joyiga chiqishdan oldin transport masofasi va tezligini baholang.", "To'xtagan transport yoki to'siq orqasidan tekshirmay chiqmang.", "Qatnov qismida va o'tish joyida telefon, video, musiqa va o'qish taqiqlanadi."], "Oldinda avtobus to'xtadi: orqasidan o'tasiz va yana qaraysiz. Tramvayning oldidan o'tasiz."],
  "20": [["Xavfsizlik sababisiz qatnov qismi va tramvay yo'lida to'xtamang.", "O'tishga ulgurmasangiz, xavfsizlik orolchasida yoki oqimlarni ajratuvchi chiziqda to'xtang.", "Xavfsiz bo'lganda va ishoralar ruxsat bergandagina davom eting."], "Yarim yo'lda ishora almashdi: markaziy orolchada kutasiz."],
  "21": [["Mayoqcha va sirena — imtiyoz belgisi.", "Piyodalar qatnov qismiga chiqmaydi, undagilar uni darhol bo'shatadi.", "Yashil chiroqda ham yo'l bering."], "Kesib o'tayotganda sirena eshitdingiz: yo'ldan chiqib, tez yordamni o'tkazasiz."],
  "22": [["Qatnov qismida emas, baland maydonchada yoki trotuarda kuting.", "Maydonchasiz bekatda transport to'liq to'xtagandan keyin yo'lga chiqing.", "Tushgach, qatnov qismini darhol bo'shating."], "Avtobusdan tushib, to'g'ri trotuarga o'tasiz."],

  "23": [["Faqat to'liq to'xtagach, trotuar yoki yo'l yoqasi tomondan chiqing va tushing.", "Imkon bo'lmasa, qatnov qismi tomondan faqat xavfsiz va xalaqit bermasa.", "Harakatdan oldin kamar taqing, ikki g'ildirakli transportda shlem kiying."], "Taksidan to'xtagach, yo'l chetiga tushasiz, harakat tasmasiga emas."],
  "24": [["Haydovchini chalg'itmang va xalaqit bermang.", "Yuk mashinasi kuzovida tik turish, bortda yoki yuk ustida o'tirish taqiqlanadi.", "Harakat paytida eshik ochish va tashqariga engashish taqiqlanadi. Haydovchi buni nazorat qiladi."], "Bola 40 km/soatda eshikni ochmoqchi: haydovchi buni to'xtatishi kerak."],

  "25": [["Imtiyoz uchun ko'k yoki qizil mayoqcha va maxsus tovushli ishora ikkalasi ham kerak.", "Ular ayrim qoidalardan faqat xavfsizlikni ta'minlab va yo'l berilgach chetga chiqishi mumkin.", "Ularning kuzatuvidagi, yaqin nuri yoqilgan mashinalar ham imtiyozdan foydalanadi."], "Mayoqchali, lekin sirenasiz militsiya mashinasida imtiyoz yo'q, u qoidalarga amal qiladi."],
  "26": [["Yaqinlashayotgan maxsus transportga va uning kuzatuvidagilarga yo'l bering.", "Ularni quvib o'tish taqiqlanadi.", "O'ngga olib, tezlikni kamaytiring, ular o'tib ketsin."], "Orqada sirenali o't o'chirish mashinasi: o'ngga olasiz, sekinlashasiz va o'tkazasiz."],
  "27": [["Mayoqchasi yoqilgan to'xtab turgan maxsus transport: tezlikni kamaytiring.", "Kerak bo'lsa darhol to'xtay oladigan darajada.", "Yonida ishlayotgan yoki o'tayotgan odamlarga e'tibor bering."], "To'xtab turgan tez yordam yonidan odimlab o'tasiz, tormozga tayyor."],
  "28": [["Zarg'aldoq yoki sariq mayoqchalar yo'l ishlari, shatakka olish, katta o'lchamli va xavfli yuklar, velosipedchilar jamlanmasini bildiradi.", "Ular imtiyoz bermaydi, faqat ogohlantiradi.", "Bunday transport ayrim qoidalardan faqat ish xavfsizligi uchun chetga chiqadi."], "Sariq mayoqchali supurgi mashinasi tasmaning yarmini egalladi: sekinlashasiz, u yo'l beradi deb kutmaysiz."],

  "31": [["Yashil: yuring. Miltillovchi yashil: yuring, lekin yashil tez tugaydi.", "Sariq: yurmang (42-banddagi holdan tashqari). Ishora almashishidan ogohlantiradi.", "Raqamli tablo yashilda necha soniya qolganini ko'rsatishi mumkin."], "Chiziqdan uzoqda sariq yondi: to'xtaysiz. Davom etish faqat to'xtash keskin tormozni talab qilsa."],
  "31r": [["Qizil va miltillovchi qizil: yurmang.", "Qizil va sariq birga: baribir to'xtang, keyingisi yashil.", "Miltillovchi sariq: ehtiyotkorlik bilan yuring. Chorraha yoki o'tish joyi tartibga solinmagan yoki xavf bor."], "Kechasi svetofor sariq miltillaydi: sekinlashasiz va chorrahani tartibga solinmagan deb hisoblaysiz."],
  "32": [["Strelka faqat o'z yo'nalishi uchun amal qiladi.", "Chapga strelka, belgi taqiqlamasa, qayrilib olishga ham ruxsat beradi.", "Qo'shimcha tarmoq o'chiq bo'lsa, o'sha yo'nalish yopiq."], "Asosiy qizil bo'lsa-yu chapga yashil strelka yonsa: burilish mumkin, lekin boshqalarga yo'l bering."],
  "34": [["Piyoda tasviri faqat piyodalarga tegishli.", "Velosiped tasviri velosipedchilar va individual harakatlanish vositalari haydovchilariga tegishli.", "Yashil ruxsat beradi, qizil taqiqlaydi."], "Velosipedchi mashinalar emas, velosiped ishorasini kutadi."],
  "35": [["Qizil X: tasma yopiq. Pastga yashil strelka: ochiq.", "1.9 chiziqli tasma ustidagi o'chiq svetofor kirishni taqiqlaydi.", "Tasma yo'nalishi kun davomida o'zgaradigan joylarda."], "O'rta tasma ustida qizil X: unga kirmaysiz."],
  "37": [["Miltillovchi oq: o'tish mumkin.", "Miltillovchi qizil: o'tish taqiqlanadi, tovushli ishora ham bo'lishi mumkin.", "Ishoralar o'chiq va poyezd ko'rinmasa, o'tish mumkin."], "Temir yo'l kesishmasida qizil chiroqlar miltillaydi: shlagbaum ko'tarilgan bo'lsa ham chiziq oldida to'xtaysiz."],
  "38": [["Qo'llar yonga yoki tushirilgan: yonlardan transport to'g'riga va o'ngga, piyodalar o'tadi. Old va orqada hamma to'xtaydi.", "O'ng qo'l oldinga: chapdan barcha yo'nalishlar, oldidan faqat o'ngga. Orqa va o'ngdan to'xtaydi.", "Qo'l yuqoriga: hamma to'xtaydi (42-banddagi holdan tashqari)."], "Xodim qo'lini ko'tardi: yashil bo'lsa ham chiziq oldida to'xtaysiz."],
  "39": [["Tartibga soluvchi yoki IIO xodimi qo'l ishorasi yoki ovoz kuchaytirgich bilan to'xtashni talab qilishi mumkin.", "Ko'rsatilgan joyda to'xtang.", "Ruxsat berilmaguncha turing."], "Xodim jezl bilan yo'l chetini ko'rsatdi: ko'rsatilgan joyda to'xtaysiz."],
  "41": [["To'xtash chizig'i oldida to'xtang, mashinaning hech bir qismi chiziqdan chiqmasin.", "Chiziq yo'q: kesishayotgan qatnov qismi chetida piyodalarga xalaqit bermay to'xtang. Temir yo'lda 119-bandga ko'ra.", "Boshqa joylarda svetofor yoki tartibga soluvchi oldida to'xtang."], "Qizil: bamperingiz chiziq ustida emas, uning orqasida turadi."],
  "42": [["Sariq yonganda yoki tartibga soluvchi qo'lini ko'targanda amal qiladi.", "Keskin tormozlamasdan to'xtay olmasangizgina davom etishingiz mumkin.", "Qatnov qismidagi piyodalar uni bo'shatishi yoki ajratuvchi chiziqda to'xtashi kerak."], "Sariq chiziq yonida tezlikda yondi: to'xtash keskin bo'lardi, shuning uchun davom etish mumkin."],
  "43": [["Tartibga soluvchi svetofor, belgi va chiziqlardan ustun.", "Svetofor imtiyoz belgilaridan ustun.", "Svetofor ishlamasa, ko'ndalang svetofor ham ishlamayotganiga ishonch hosil qilgach ehtiyotkorlik bilan davom eting."], "Svetofor qizil, lekin xodim o'tishga ishora qilmoqda: ehtiyotkorlik bilan yurasiz."],

  "44": [["Ogohlantiruvchi ishoralar: burilish chiroqlari yoki qo'l ishoralari, to'xtash chiroqlari, tovushli ishora.", "Shuningdek farani yoqib-o'chirish va kunduzi yaqin nur.", "Ogohlantirish hech qachon imtiyoz bermaydi."], "Aholi punktidan tashqarida quvib o'tishdan ogohlantirish uchun faralarni miltillatasiz."],
  "45": [["Harakatni boshlash, qayta tizilish, burilish va to'xtashdan oldin ishora bering.", "Chiroqsiz qo'l bilan: chapga — chap qo'l yonga yoki o'ng qo'l bukilib yuqoriga. O'ngga — o'ng qo'l yonga yoki chap qo'l yuqoriga.", "To'xtash: istalgan qo'lni ko'taring."], "Burilish ko'rsatkichi buzilgan: burilishni qo'l bilan ko'rsatasiz."],
  "46": [["Ishorani oldinroq bering va manyovrdan keyin darhol o'chiring.", "Ishoralar boshqalarni chalg'itmasin.", "Ishora imtiyoz bermaydi va ehtiyotkorlikdan ozod etmaydi."], "O'ng ishorani yoqdingiz, lekin yonida mashina bor: kutasiz."],
  "47": [["Orqada hech kim quvib o'tmayotganiga yoki boshlamaganiga ishonch hosil qiling.", "Hech kimga xalaqit bermasligingizga ishonch hosil qiling.", "Faqat shundan keyin ishora bering va qayta tizilib oling."], "Chap tasmaga o'tishdan oldin oynaga va ko'r zonaga qaraysiz."],
  "48": [["Aholi punktidan tashqarida signal quvib o'tishdan ogohlantiradi.", "Istalgan joyda hodisaning oldini olish uchun chalinishi mumkin.", "Faralarni miltillatish quvib o'tish signalini almashtirishi yoki to'ldirishi mumkin."], "Shaharda sekin mashinaga signal chalmaysiz. Faqat bola yugurib chiqsa chalasiz."],
  "50": [["Avariya ishorasi xavfni bildiradi: barcha ko'rsatkichlar miltillaydi.", "Hodisadan keyin, taqiqlangan joyda majburiy to'xtaganda, ko'z qamashganda, shatakka olishda va «Bolalarni tashish» belgili transportga bolalar chiqayotganda yoqing.", "Shuningdek transport xavf tug'dirishi mumkin bo'lgan har qanday holda."], "Ko'prikda shina teshildi: avariya chiroqlarini yoqib, belgini qo'yasiz."],
  "51": [["Avariya chiroqlari ishlamasa, belgini darhol qo'ying.", "Aholi punktlarida transportdan kamida 15 m, tashqarisida kamida 30 m orqada.", "Hodisa va taqiqlangan yoki ko'rinishi cheklangan joydagi majburiy to'xtashda qo'llaniladi."], "Shahardan tashqarida mashina buzildi: kamida 30 m orqaga borib, belgini qo'yasiz."],

  "53": [["Harakatni boshlash, qatorni almashtirish, burilish, qayrilib olish, quvib o'tish va to'xtashga tegishli.", "Manyovr hech kimga xavf tug'dirmasligi kerak.", "Avval oynalar, ko'r zona va oldinni tekshiring."], "Yo'l chetidan chiqishdan oldin yelka orqali qaraysiz va velosipedchini o'tkazasiz."],
  "54": [["Hovli, to'xtab turish joyi, yonilg'i quyish shoxobchasi va boshqa yondosh hududdan chiqishda yo'ldagi barchaga yo'l bering.", "Chiqish yo'lingizni kesayotgan piyoda va velosipedchilarga ham.", "Bunday chiqishlar chorraha hisoblanmaydi."], "Yoqilg'i quyish joyidan chiqayotib avtobus va piyodalarni kutasiz."],
  "55": [["Qatorni to'g'ri ketayotganlarga yo'l berib almashtiring.", "Bir yo'nalishda bir vaqtda: o'ngdagiga yo'l bering.", "Ishoradan oldin orqaga qarang."], "Ikki tasma qo'shilmoqda: o'ng tomoningizdagi mashina birinchi o'tadi."],
  "56": [["Oldindan egallang: o'ngga — o'ng chet, chapga va qayrilib olish — chap chet.", "Istisno: aylanma chorrahaga kirish uchun burilish.", "O'rtadagi tramvay yo'lidan belgi yoki chiziq taqiqlamasa va tramvayga xalaqit bermasangiz chapga burilishda foydalanish mumkin."], "Chap tasmaga oxirgi metrda emas, oldindan o'tasiz."],
  "57": [["Chorrahadan chiqayotganda qarama-qarshi tomonga o'tib ketmang.", "O'ngga burilishda iloji boricha o'ng chetga yaqin bo'ling.", "Shunday qila olmaydigan uzun transport faqat xavfsiz bo'lsa va xalaqit bermasa chetga chiqadi."], "Uzun yuk mashinasi keng aylanadi, lekin faqat yonida hech kim yo'qligiga ishonch hosil qilgach."],
  "59": [["Chorrahadan tashqarida chapga burilish va qayrilib olishda qarama-qarshi transport va bir yo'nalishdagi tramvayga yo'l bering.", "Yo'l chapdan qayrilish uchun tor bo'lsa, o'ng chetdan boshlash mumkin.", "Shunda ikkala yo'nalishdagilarga yo'l berasiz."], "Hovliga chapga burilmoqdasiz: kesishdan oldin qarama-qarshi mashinalarni kutasiz."],
  "60": [["Yo'llar kesishganda va Qoidalarda navbat belgilanmaganda amal qiladi.", "O'ngdan yaqinlashayotgan transport birinchi o'tadi.", "Bu teng chorrahalardagi fikr bilan bir xil."], "Belgisiz to'xtab turish joyida ikki mashina uchrashdi: o'ng tomonida boshqasi bor mashina yo'l beradi."],
  "62": [["Piyodalar o'tish joylarida, tunnellarda, ko'prik, yo'l o'tkazgich, estakadalarda va ularning ostida, temir yo'l kesishmalarida qayrilib olish taqiqlanadi.", "Ko'rinish istalgan yo'nalishda 100 m dan kam joyda ham taqiqlanadi.", "Belgi ko'priklarda va shunga o'xshash joylarda ruxsat berishi mumkin."], "Tepalikdan keyin ko'rinish 50 m: qayrilib olmaysiz."],
  "63": [["Orqaga faqat xavfsiz bo'lsa va xalaqit bermasa yuring.", "Ko'rinmasa, yordamchidan foydalaning.", "Chorrahalarda va qayrilish taqiqlangan joyda orqaga yurish taqiqlanadi."], "Hovlidan orqaga chiqayotib, yordamchidan trotuarni kuzatishni so'raysiz."],

  "64": [["Ikki tomonlama yo'lning chap yarmi qarama-qarshi harakat uchun.", "Tramvay yo'li, ajratuvchi tasma, 1.1 yoki 1.3 chiziq yoki chapda uzuq tomonli 1.11 chiziq ajratgan joyda unga chiqish taqiqlanadi.", "Yarim qo'shimcha tasmalarni hisobga olmay sanaladi: sekinlashish, ko'tarilish va bekat cho'ntaklari."], "O'rtada sidirg'a chiziq: g'ildiraklaringiz o'z tomoningizda qoladi."],
  "65": [["To'rt va undan ortiq tasmali yo'llarda qarama-qarshi tasmalar yopiq.", "Bunday yo'llarni 1.3 chiziq ajratadi.", "Quvib o'tish o'z yo'nalishingiz tasmalarida bo'ladi."], "To'rt tasmali prospektda o'z yo'nalishingizdagi chap tasmada quvib o'tasiz, qarama-qarshisida emas."],
  "66": [["Uch tasmali yo'lda o'rta tasma ikkala yo'nalish uchun umumiy.", "Undan faqat quvib o'tish, aylanib o'tish, chapga burilish va qayrilib olish uchun foydalaning.", "Chetki chap tasma qarama-qarshi harakat uchun: hech qachon unga chiqmang."], "Chapga burilish uchun o'rta tasmaga kirasiz, ikki tomonga qaraysiz va burilasiz."],
  "67": [["O'ng tomonda, iloji boricha chetga yaqin yuring.", "O'ng tasmalar bo'sh bo'lsa, chapni egallamang.", "Aholi punktlarida qulay tasmadan foydalanish mumkin, lekin boshqalar band bo'lsa faqat burilish, qayrilish, to'xtash yoki to'siqni aylanib o'tish uchun almashtiring."], "Shahardan tashqarida bo'sh uch tasmali yo'lda o'ng tasmada yurasiz."],
  "68": [["Tezligini 40 km/soatdan oshira olmaydigan yoki oshirmasligi kerak transport o'ng tasmada yuradi.", "Undan faqat quvib o'tish, aylanib o'tish, chapga burilish, qayrilib olish yoki ruxsat etilgan joyda to'xtash uchun chiqadi.", "Sekin traktorlar ham shu guruhga kiradi."], "Sekin traktor o'ng tasmada qoladi va faqat chapga burilish uchun chiqadi."],
  "69": [["Chapdagi bir yo'nalishdagi tramvay yo'lidan boshqa tasmalar band bo'lganda tramvayga xalaqit bermay foydalanish mumkin.", "Qarama-qarshi yo'nalishdagi tramvay yo'li taqiqlanadi.", "Chorrahadan oldingi belgi taqiqlasa, chorrahadan o'tishda yo'llardan yurmang."], "Tirbandlik tasmalaringizni to'ldirdi: chap tramvay yo'lidan yurish mumkin, lekin yaqinlashgan tramvayga yo'l bering."],
  "70": [["Tasmalar chiziqlar bilan belgilangan joyda qat'iy o'z tasmangizda yuring.", "Uzuq chiziqlarni faqat qayta tizilishda kesib o'tiladi.", "Sidirg'a chiziqlarni kesib o'tish mumkin emas."], "Uzuq chiziqni bir marta kesib o'tib, yangi tasmada tekis yurasiz, chiziq ustida emas."],
  "71": [["Reversiv yo'lga burilganda burilishni chetki o'ng tasmada tugating.", "Boshqa tasmalarga keyinroq, ular sizning yo'nalishingizga ruxsat berishiga ishonch hosil qilgach o'ting.", "Reversiv tasmalar 1.9 chiziq va svetoforlar bilan ko'rsatiladi."], "Chorrahadan avval o'ng tasmaga chiqasiz va ishoralar ruxsat bergach o'tasiz."],
  "72": [["Qoidalarda ruxsat berilganidan tashqari ajratuvchi mintaqa, yo'l yoqasi, trotuar, yo'lka, velosiped tasmasi va yashil hududlarda harakatlanish taqiqlanadi.", "Yo'l va kommunal xizmat mashinalari hamda do'kon va binolarga boshqa yo'li yo'q transport xavfsiz bo'lsa yaqin joygacha kirishi mumkin.", "Taqiq piyodalar va velosipedchilarni himoya qiladi."], "Yetkazib berish furgoni trotuarga faqat yuk tushirish uchun zarur joygacha va boshqa yo'li bo'lmasa kiradi."],
  "73": [["Oldingi mashina keskin tormozlaganda to'qnashmaslik masofasini saqlang.", "Xavfsiz yon oraliqni ham saqlang.", "Aniq raqam yo'q. Tezlik, ob-havo va yuk uni o'zgartiradi, ikki soniya esa qulay mezon."], "Nam yo'lda masofani ikki baravar oshirasiz."],
  "75": [["To'siq sizning tomoningizda: yo'l berasiz.", "Bo'sh tomondagi haydovchi birinchi o'tadi.", "Ikki transport o'tolmaydigan tor yo'llarda amal qiladi."], "To'xtab turgan yuk mashinasi yo'lni sizning tomoningizda toraytirdi: to'xtab, qarama-qarshi mashinani o'tkazasiz."],

  "77": [["Tezlik oqim, transport va yuk, yo'l, ob-havo va ko'rinishga mos bo'lsin.", "U doim boshqaruvni saqlashga va Qoidalarga amal qilishga imkon bersin.", "Xavf paydo bo'lsa, sekinlashing, to'xtang yoki xavfsiz aylanib o'ting."], "Kuchli yomg'irda ruxsat etilgandan sekinroq yurasiz."],
  "78": [["Aholi punktlarida 70 km/soatgacha.", "Belgi qo'yilgan maktab va maktabgacha tashkilotlarga yetmasdan va o'tib 300 m ichida 30 km/soatgacha.", "Turar joy dahalari va hovlilarda 20 km/soatgacha."], "Maktab darvozasi oldida 70 ruxsat etilgan ko'chada ham 30 km/soatda yurasiz."],
  "78b": [["Nukus, Toshkent, viloyat va tuman markazlari hamda shaharlarda 60 km/soatgacha.", "Mahalliy hokimiyatlar yo'l uchastkalari uchun belgilar bilan chegara belgilashi mumkin.", "Yo'ldagi belgi umumiy chegaradan ustun."], "Shahar markazida belgi kamroq demasa chegara 60 km/soat."],
  "79": [["Yengil va 3,5 t gacha yuk mashinalari: 100 km/soat.", "Shaharlararo avtobus va mikroavtobuslar: 90 km/soat.", "Boshqa avtobuslar, tirkamali yengil mashinalar, mototsikllar va 3,5 t dan ortiq yuk mashinalari: 80. Tirkamali yuk mashinalari: 70."], "Tirkamali yengil mashina trassada 80 km/soatda yuradi."],
  "80": [["Yukxonasida odam tashiyotgan yuk mashinalari: 60 km/soat.", "Bolalar guruhi tashkiliy tashilganda: 60 km/soat.", "Shatakka olishda 50 km/soat. Xavfli, og'ir va katta o'lchamli yuklar: DYHXX bilan kelishilgan tezlik."], "Buzilgan mashinani shatakka olasiz: chegarangiz 50 km/soat."],
  "81": [["Transport vositasining eng yuqori tezligidan va «Tezlik cheklangan» belgisidagidan oshmang.", "Zaruratsiz juda sekin yurib xalaqit bermang.", "Hodisaning oldini olish uchun bo'lmasa, keskin tormozlamang."], "Tez yo'lda sababsiz 20 km/soatda o'rmalaysiz: hodisaga sabab bo'lishingiz mumkin."],

  "82": [["Chap burilish ishorasini yoqing.", "Oldingi tasma yetarlicha masofada bo'sh, orqadagi boshlamagan, oldindagi ishora bermayotganiga ishonch hosil qiling.", "Quvib o'tilganga xalaqit bermay qaytib kira olishingiz kerak."], "Oldinda yuk mashinasi: oynaga qaraysiz, ishora berasiz va uzun bo'sh joyda quvib o'tasiz."],
  "83": [["Transportni har ikki tomondan o'zib ketish mumkin.", "Chapga ishora berib burilishga kirishgan transport o'ng tomondan o'zib ketiladi.", "Qoidalar qarama-qarshi tasmaga chiqmay o'tishni o'zib ketish, chiqib o'tishni quvib o'tish deydi."], "Oldingi mashina chapga ishora berib burildi: siz uni o'ng tomondan o'zib ketasiz."],
  "84": [["Sizni quvib o'tayotganda tezlikni oshirmang.", "Quvib o'tishga to'sqinlik qiladigan boshqa narsa qilmang.", "Tezlikni saqlang yoki biroz kamaytirib, o'ngroqda yuring."], "Orqadagi mashina quvib o'tishga chiqdi: tezlikni saqlaysiz yoki biroz sekinlashasiz."],
  "85": [["Quvib o'tgach o'z tasmangizga qayting.", "Quvib o'tilganga xalaqit bermay qaytsangizgina.", "So'ng ko'rsatkichni o'chiring."], "Yuk mashinasini quvib o'tdingiz, oynada uning old qismini ko'rdingiz, o'ng ishorani berib qaytdingiz."],
  "86": [["Tartibga solingan chorrahalarda va tartibga solinmagan chorrahalarda asosiy bo'lmagan yo'lda taqiqlanadi.", "Ko'prik, yo'l o'tkazgich, estakadalarda va ularning ostida hamda piyodalar o'tish joylarida taqiqlanadi.", "Temir yo'l kesishmalarida va ulargacha 100 m, tepalik oxirida va ko'rinish cheklangan joylarda taqiqlanadi."], "«Zebra»ga yaqinlashayotganda hech qachon quvib o'tmaysiz."],
  "87": [["Aholi punktlaridan tashqarida sekin yoki katta hajmli transport iloji boricha o'ngga olishi kerak.", "Kerak bo'lsa to'xtab, orqadagi navbatni o'tkazsin.", "Bu xavfli quvib o'tishning oldini oladi."], "Orqasida o'nta mashina bor sekin traktor keng joyda chetga chiqadi."],

  "88": [["Yo'lning o'ng tomonida yo'l yoqasida, u bo'lmasa qatnov qismi chetida to'xtang va to'xtab turing.", "Trotuarda faqat 89-bandda ruxsat etilgan joyda.", "Chapda: aholi punktlarida bir tomonlama va har tomonga bitta tasmali tramvaysiz yo'llarda. 3,5 t dan og'ir yuk mashinalari u yerda faqat yuk ortish va tushirish uchun."], "Shaharda bir tomonlama ko'chada chap tomonda to'xtab turish mumkin."],
  "89": [["Bir qatorda, qatnov qismi chetiga parallel qo'ying.", "Kajavasiz ikki g'ildirakli transport xalaqit bermasa ikki qatorda qo'yishi mumkin.", "Trotuarda faqat to'xtab turish belgisi va qo'shimcha belgi ruxsat bergan joyda."], "Mashinani yo'l chetiga parallel qo'yasiz, burchak ostida emas."],
  "91": [["Tramvay yo'llarida, temir yo'l kesishmalarida va tunnellarda to'xtash taqiqlanadi.", "Har yo'nalishda uchtadan kam tasmali ko'prik va estakadalar ustida va belgi ruxsat bermasa ostida taqiqlanadi.", "Boshqa transportga xalaqit beradigan joylarda taqiqlanadi."], "Temir yo'l kesishmasida bir soniya ham to'xtamaysiz."],
  "91b": [["Piyodalar o'tish joyida va undan oldin 10 m dan kam masofada.", "Velosiped yo'lkasi kesishuvida va undan oldin 10 m dan kam masofada.", "Velosiped tasmasida, yo'lovchi chiqarish va tushirishdan tashqari."], "«Zebra»dan 3 m emas, 12 m oldin to'xtaysiz."],
  "91c": [["Qatnov qismlari kesishmalarida va kesishayotgan qatnov qismi chetidan 30 m dan kam masofada.", "Istisno: uch tomonlama chorrahada sidirg'a chiziq yoki ajratuvchi mintaqa bilan ajratilgan qarama-qarshi tomon.", "Shuningdek qayrilib olish joylarida va undan oldin va keyin 30 m ichida."], "O'ng tomonda yon ko'cha tutashgan: uning chetidan 30 m ichida to'xtab turmaysiz."],
  "91d": [["Bekat maydonchalarida va bekatdan oldin va keyin 15 m dan kam masofada.", "Istisno: yo'nalishli transportga xalaqit bermay yo'lovchi chiqarish yoki tushirish uchun qisqa to'xtash.", "Bekatni 1.17 chiziq belgilashi mumkin."], "Do'stingizni avtobus bekatidan 5 m emas, 20 m uzoqda kutasiz."],
  "91e": [["Mashina bilan sidirg'a chiziq, ajratuvchi mintaqa yoki qarama-qarshi chet orasi 3 m dan kam joyda.", "Ko'rinish 100 m dan kam do'ngliklar va xavfli burilishlar yaqinida.", "Svetofor va belgilarni to'sadigan, chiqishni to'sadigan yoki piyodalarga xalaqit beradigan joyda."], "Sidirg'a chiziqli tor ko'chada 3 m bo'sh qolsagina to'xtaysiz."],
  "92": [["To'xtash taqiqlangan har qanday joyda to'xtab turish ham taqiqlanadi.", "Shuningdek temir yo'l kesishmasining har ikki tomonida 50 m yaqinida.", "To'xtab turish taqiqlovchi belgilar, 1.4 va 1.10 chiziqlar ostida va og'ir yuk mashinalarini kechasi xavfli holatda qoldirish."], "Mashinani temir yo'l kesishmasidan 20 m emas, 100 m uzoqda qoldirasiz."],
  "93": [["Taqiqlangan joyda majburiy to'xtasangiz, ketishning barcha choralarini ko'ring.", "Transportni yo'l chetiga va o'sha joydan olib chiqing.", "Shu orada avariya chiroqlari va belgidan foydalaning."], "Ko'prikda shina teshildi: imkon bo'lsa, xavfsiz joygacha borasiz."],
  "94": [["Boshqalarga xalaqit beradigan yoki xavf tug'diradigan bo'lsa, eshikni ochmang.", "Ochishdan oldin velosipedchi va mashinalarni tekshiring.", "Yo'lovchilar ham shunday ehtiyotkor bo'lsin."], "Velosiped tasmasi tomonga eshik ochishdan oldin oynaga qaraysiz."],
  "95": [["Mashina o'z-o'zidan harakatlanib ketmasligini ta'minlagach o'rningizni tashlang.", "O'zi yo'qligida foydalanishni istisno qiling: qulflang va kalitni oling.", "Qiyalikda g'ildiraklarni yo'l chetiga buring."], "Qo'l tormozini tortasiz, dvigatelni o'chirasiz va mashinani qulflaysiz."],

  "96": [["Chapga yoki o'ngga burilganda kirayotgan yo'lingizni kesib o'tayotgan piyodalarga yo'l bering.", "Velosiped yo'lkasidan kesib o'tayotgan velosipedchi va elektrosamokat haydovchilariga ham.", "Bu tartibga solingan va solinmagan chorrahalarga bir xil tegishli."], "Yashilda o'ngga burilasiz, yon ko'chani piyodalar kesmoqda: kutasiz."],
  "97": [["Tirbandlik tufayli to'xtab ko'ndalang harakatni to'ssangiz, chorrahaga kirmang.", "To'xtash chizig'idan o'tgan bo'lsangiz, qatnov qismlari kesishmasiga kirmang.", "Yashil bo'lsa ham chorraha oldida kuting."], "Oldinda navbat: yashil bo'lsa ham chorraha oldida kutasiz."],
  "98": [["Tartibga solingan: navbatni svetofor yoki tartibga soluvchi belgilaydi.", "Tartibga solinmagan: miltillovchi sariq, ishlamayotgan svetoforlar yoki tartibga soluvchi yo'q.", "Aylanma harakat: aylanadagilar birinchi o'tadi."], "Aylanma chorrahaga kirayotib, aylanadagi mashinalarga yo'l berasiz."],
  "99": [["Yashilda chapga burilayotgan haydovchi to'g'riga yoki o'ngga ketayotgan qarama-qarshi transportga yo'l beradi.", "Tramvaylar ham shu qoidaga amal qiladi.", "Piyodalarga ham yo'l beriladi."], "Chorraha o'rtasida bo'shliqni kutasiz va qarama-qarshi tasma bo'sh bo'lganda burilasiz."],
  "100": [["Asosiy qizil yoki sariq yonganda qo'shimcha tarmoqdagi yashil strelka.", "Boshqa yo'nalishlardan kelayotgan transportga yo'l berasiz.", "Tramvaylar ham yo'l beradi."], "Asosiy qizil, o'ngga yashil strelka: yurasiz, lekin ko'ndalang oqim va piyodalarga yo'l berasiz."],
  "101": [["Tramvay va mashinalarga bir vaqtda yashil yonsa, tramvay birinchi.", "Yo'nalish ahamiyatsiz.", "Qizil yonganda yashil strelka bo'yicha ketayotgan tramvay boshqalarga yo'l beradi."], "Siz chapga burilasiz, tramvay to'g'ri ketmoqda: uni o'tkazing."],
  "102": [["Yashilda kirgan bo'lsangiz, o'z yo'nalishingizda davom eting.", "Istisno: chorraha ichidagi svetoforlar oldida to'xtash chiziqlari yoki belgi.", "Katta chorrahada sizga tegishli har bir svetoforga amal qiling."], "Keng chorrahada o'rtadagi ikkinchi svetofor qizil bo'lsa, to'xtaysiz."],
  "103": [["Yashilda chorrahadan o'tishni tugatayotgan transportga yo'l bering.", "O'tishni tugatayotgan piyodalarga yo'l bering.", "Yashil allaqachon o'tayotganlarni bekor qilmaydi."], "Yashil yondi, piyoda hali «zebra»da: kutasiz."],

  "104": [["Ahamiyati har xil yo'llar: ikkinchi darajali yo'l keyingi yo'nalishidan qat'i nazar asosiyga yo'l beradi.", "Tramvay teng yo'ldagi mashinalardan ustun.", "Qaysi yo'l asosiy ekanini belgilar hal qiladi."], "Shag'alli ko'chadan asfaltli yo'lga chiqasiz: yo'l berasiz."],
  "105": [["Teng yo'llar: o'ngdagi transportga yo'l bering.", "Tramvay yo'nalishidan qat'i nazar birinchi.", "Tramvay haydovchilari o'zaro o'ng qo'l qoidasiga amal qiladi."], "Qishloq chorrahasida o'ng tomondan mashina yaqinlashmoqda: kutasiz."],
  "106": [["Asosiy yo'l chorrahada buriladi.", "Asosiy yo'ldagi haydovchilar o'zaro teng yo'llar qoidasiga amal qiladi.", "Ikkinchi darajali yo'ldagilar ham shunday."], "Egilgan asosiy yo'lda ikki mashina chorrahada uchrashdi: o'ng tomondagisi birinchi o'tadi."],
  "107": [["Teng yo'ldan chapga burilish va qayrilib olishda to'g'riga yoki o'ngga ketayotgan qarama-qarshi transportga yo'l bering.", "Tramvaylar ham shunday.", "Piyodalar birinchi (96-band)."], "Teng chorrahada chapga burilasiz, qarshidan mashina to'g'ri kelmoqda: kutasiz."],
  "108": [["Yo'lingizda qoplama bor-yo'qligini aniqlay olmaysiz, masalan qorong'i, loy yoki qorda.", "Va imtiyoz belgilari yo'q.", "Yo'lni ikkinchi darajali deb hisoblang."], "Qorli yo'lda o'zingizni ikkinchi darajali yo'lda deb hisoblab, yo'l berasiz."],

  "109": [["Sizning yo'nalishingizda kesib o'tayotgan piyodalar uchun sekinlashing yoki to'xtang.", "Ular endigina chiqqan bo'lsa ham tayyor bo'ling.", "Har bir tartibga solinmagan o'tish joyiga tegishli."], "«Zebra»da bolani ko'rdingiz: to'xtaysiz."],
  "110": [["Mashina tartibga solinmagan o'tish joyida sekinlashdi yoki to'xtadi.", "Qo'shni tasmadagilar uning oldida hech kim yo'qligiga ishonch hosil qilgachgina davom etadi.", "Bu «ikkinchi qator» hodisalarining oldini oladi."], "Yoningizdagi mashina to'xtadi: o'tish joyi bo'shligini ko'rmaguncha siz ham to'xtaysiz."],
  "111": [["Tartibga solingan o'tish joylarida sizga yashil bo'lsa ham piyodalar o'tib bo'ladi.", "Bolalar va qariyalarga vaqt bering.", "O'tish joyi bo'shamaguncha yurmang."], "Yashil yondi, lekin yo'l o'rtasida buvi bor: kutasiz."],
  "112": [["«Zebra»dan keyingi tirbandlik unda to'xtashga majbur qilsa, kirmang.", "O'tish joyida hech qachon to'xtamang.", "«Zebra» oldida joy bo'shaguncha kuting."], "Oldinda navbat: chiziqlar oldida to'xtaysiz."],
  "113": [["Oq hassali ko'zi ojiz piyoda: hamma joyda o'tkazing.", "O'tish joylaridan tashqarida ham.", "U qatnov qismini bo'shatguncha kuting."], "Oq hassali kishi kvartal o'rtasida kesib o'tmoqda: to'xtaysiz."],
  "114": [["Yo'lovchilar qatnov qismida yoki undagi maydonchada chiqadi va tushadi.", "Eshiklarga borayotgan yoki undan kelayotgan piyodalarga yo'l bering.", "To'xtagan tramvay va avtobuslar oldida to'xtashga tayyor bo'ling."], "Odamlar bekat orolchasidan tramvayga o'tmoqda: orqasida to'xtaysiz."],
  "115": [["«Bolalarni tashish» belgili va avariya chiroqli transport to'xtadi.", "Sekinlashing, kerak bo'lsa to'xtang va bolalarni o'tkazing.", "Bolalar to'satdan yugurib chiqishi mumkin."], "«Bolalar» belgili va avariya chiroqli avtobus to'xtadi: sekinlashib kutasiz."],
  "1152": [["Yo'nalishli transport tasmasi bor yo'lda boshqa transport unda yura olmaydi.", "Istisno: tezkor xizmatlar.", "Yondosh hududga borish uchun kirishgacha yoki eng yaqin uzuq chiziqgacha 50 m ichida, yo'nalishli transportga yo'l berib kirish mumkin."], "Yoqilg'i quyish joyiga borish uchun avtobus tasmasini faqat oxirgi 50 m da kesib o'tasiz."],

  "116": [["Temir yo'llarni faqat temir yo'l kesishmalaridan kesib o'ting.", "Poyezd, lokomotiv va drezinalarga yo'l bering.", "Boshqa joyda hech qachon kesib o'tmang."], "Panjaradagi teshikdan emas, kesishmadan o'tasiz."],
  "117": [["Navbatchi, svetofor, belgi, chiziq va shlagbaum holatiga amal qiling.", "Poyezd yaqinlashmayotganiga ishonch hosil qiling.", "Ikki tomonga qarang, sukunatga ishonmang."], "Shlagbaumsiz kesishmada to'xtab, qarab va quloq solasiz."],
  "118": [["Shlagbaum yopiq yoki yopilmoqda: kirish taqiqlanadi.", "Taqiqlovchi svetofor: shlagbaum ko'tarilgan bo'lsa ham kirish taqiqlanadi.", "Navbatchi taqiqlasa, tirbandlik kesishmada to'xtatib qo'ysa yoki poyezd ko'rinsa ham."], "Signal jiringlayapti: shlagbaum hali qimirlamagan bo'lsa ham to'xtaysiz."],
  "119": [["To'xtash chizig'i, belgi yoki svetofor oldida to'xtang.", "Ular bo'lmasa shlagbaumdan kamida 5 m oldin.", "Shlagbaum yo'q: birinchi relsdan kamida 10 m oldin."], "Shlagbaumdan 6 m oldin to'xtadingiz."],
  "120": [["Kesishmada majburiy to'xtash: odamlarni tushiring va kesishmani darhol bo'shating.", "Imkon bo'lsa, ikki kishini yo'l bo'ylab ikki tomonga 1 000 m ga yoki bittasini ko'rinish yomon tomonga yuboring.", "Transport yonida qoling va umumiy xatar ishorasini bering. Poyezdga to'xtash ishorasini bering."], "Dvigatel o'chdi: avval hammani tushirasiz, keyin yordam chaqirasiz."],

  "121": [["Taqiqlanadi: piyodalar, hayvonlar, aravalar, velosipedlar, elektrosamokatlar, mopedlar, traktorlar va tezligi 40 km/soatdan kam transport.", "Taqiqlanadi: maydonchalardan tashqarida to'xtash, orqaga yurish, ajratuvchi bo'lakdagi uzilishlarda qayrilish, o'rgatish.", "Yuk mashinalari chetki chap tasmada yurmaydi."], "Chiqish yo'lagini o'tkazib yubordingiz: keyingisigacha borasiz, hech qachon orqaga yurmaysiz."],
  "122": [["Qatnov qismida majburiy to'xtash: transportni avariya chiroqlari va belgi bilan belgilang.", "Chekka chiziqdan o'ngdagi maxsus tasmaga olib chiqing.", "Qatnov qismini tark etishning barcha choralarini ko'ring."], "Avtomagistralda dvigatel nosoz: yo'l chetiga yurib chiqasiz."],

  "123": [["Hududga kirish va chiqish belgilar bilan ko'rsatilgan.", "Piyodalar trotuar va qatnov qismidan yuradi.", "Ular imtiyozga ega, lekin transportga asossiz xalaqit bermasligi kerak."], "Bolalar ko'chada o'ynayapti: odimlab yurasiz."],
  "124": [["O'rgatish taqiqlanadi.", "Dvigatel ishlab turgan holda to'xtab turish taqiqlanadi.", "3,5 t dan og'ir yuk mashinalari faqat ajratilgan joylarda."], "Kutganingizda dvigatelni o'chirasiz."],
  "125": [["Piyodalarni himoya qiling.", "Inshoot, qurilma va o'simliklarni shikastlamang.", "20 km/soat chegarasi amal qiladi."], "Gulzor ustidan yurmaysiz."],
  "126": [["Hududdan chiqishda barcha yo'l harakati ishtirokchilariga yo'l bering.", "Chiqishni yondosh hududdan chiqish kabi hisoblang.", "Transport va velosipedchilarga qarang."], "Hovlidan chiqib, o'tayotgan mashinalarni kutasiz."],

  "128": [["Belgilangan tik nishablikda to'siq o'tishga xalaqit bersa, pastga ketayotgan haydovchi yo'l beradi.", "Pastga ketayotgan transportni to'xtatish qiyinroq.", "Bu ko'tarilish va tushishga tegishli."], "To'xtab turgan mashina tik ko'chani toraytirdi: pastga tushayotgan haydovchi kutadi."],
  "129": [["Tik nishablik yoki dovonda tormoz ishlamay qoldi.", "Xotirjam bo'ling, dvigatel bilan tormozlang va avariyali yo'lga yo'naltiring.", "Bunday yo'llar oldindan belgilanadi."], "Uzun tushishda tormoz qizib ketdi: avariyali yo'lga yo'naltirasiz."],

  "131": [["Tramvay yo'llari chorrahadan tashqarida qatnov qismini kesib o'tgan joyda tramvay imtiyozga ega.", "Istisno: depodan chiqish joylari.", "Tramvay yaqinlashganda yo'llar oldida to'xtang."], "Tramvay yo'li yo'lingizni chorrahadan tashqarida kesadi: to'xtaysiz."],
  "132": [["Yo'nalishli transport tasmasida boshqalar yura olmaydi va to'xtay olmaydi.", "Uzuq chiziq bilan ajratilgan bo'lsa, burilmoqchi transport burilish uchun kirishi mumkin.", "Yo'ldan chiqish yoki o'ngda odam chiqarish va tushirish uchun kirish yo'nalishli transportga xalaqit bermasa mumkin."], "O'ngga burilishdan oldingi oxirgi metrlarda, ruxsat etilgan joyda avtobus tasmasiga kirasiz."],
  "133": [["Aholi punktlarida bekatdan chiqayotgan avtobus va trolleybuslarga yo'l bering.", "Ularning haydovchilari yo'l berilganiga ishonch hosil qilgach yuradi.", "Yo'lovchi faqat bekatlarda olinadi va tushiriladi, yo'nalishli taksilar bundan mustasno."], "Avtobus ishora berdi: uni chiqarib yuborasiz."],

  "134": [["Qorong'ida va yomon ko'rinishda, tunnellarda esa doim talab etiladi.", "Mexanik transport: uzoq yoki yaqin nurli faralar.", "Tirkama va shatakka olinganlarda gabarit chiroqlari. Velosipedlarda chiroq (bo'lsa)."], "Tushda tunnelga kirasiz va chiroqlarni yoqasiz."],
  "135": [["Yo'l yoritilgan joyda yaqin nur.", "Qarama-qarshi transportgacha 150 m qolganda, qarshidagi miltillatsa ertaroq o'ting.", "Ko'zni qamashtirishi mumkin bo'lgan har qanday holda, oldingi mashinani ham."], "Qarshidan mashinani 200 m da ko'rishingiz bilan yaqin nurga o'tasiz."],
  "136": [["Qorong'ida yoritilmagan yo'lda to'xtagan yoki to'xtab turgan transportda gabarit chiroqlari yoniq.", "Yomon ko'rinishda ham shunday.", "Yaqin nur va tumanga qarshi farani qo'shish mumkin."], "Kechasi yo'l chetida gabarit chiroqlari yoniq holda to'xtab turasiz."],
  "138": [["Kunduzi yaqin nur kolonnada, yo'lovchili avtobuslarda va bolalarni tashishda.", "Shuningdek xavfli, katta o'lchamli va og'ir yuklarni tashishda, shatakka olishda, kuchli yomg'ir yoki qorda.", "Mototsikl, elektromototsikl, skuter va moped doim."], "Tushda bo'ronli qorda yaqin nur bilan yurasiz."],
  "140": [["Orqa tumanga qarshi chiroqlar faqat yomon ko'rinishda.", "Ularni hech qachon to'xtash chiroqlariga ulamang.", "Ko'rinish tiklangach o'chiring."], "Tuman tarqaldi: orqadagi haydovchining ko'zini qamashtirmaslik uchun orqa tumanga qarshi chiroqni o'chirasiz."],

  "142": [["Shatakka olingan transportni haydovchi boshqarishi kerak.", "Istisno: izidan yurishini ta'minlaydigan qattiq ulagich.", "Harakatdan oldin ulagichni tekshiring."], "Mashinani shatakka olasiz, uning rulida haydovchi o'tiradi."],
  "143": [["Shatakka olingan avtobus, trolleybus va yuk mashinasi yukxonasida odam bo'lmasin.", "Qisman ortishda ikkala transportning kabinasi va yukxonasida hech kim bo'lmasin.", "Taqiq yo'lovchilarni himoya qiladi."], "Shatakka olingan mikroavtobusda yo'lovchi tashimaysiz."],
  "144": [["Egiluvchan ulagich: masofa 4 — 6 m.", "Qattiq ulagich: masofa 4 m gacha.", "Egiluvchan ulagich bayroqchalar yoki belgi bilan belgilanadi."], "Arqoningiz 5 m va qizil-oq bayroqchali."],
  "145": [["Taqiqlanadi: rul ishlamasa, ikki va undan ko'p transportni, butun tarkib 20 m dan oshsa.", "Taqiqlanadi: ikki g'ildirakli mototransportni va sirpanchiq yo'lda egiluvchan ulagichda.", "Tormozi ishlamaydigan og'ir transportni faqat qattiq ulagich yoki qisman ortish bilan."], "Muzda qattiq ulagichni kutasiz."],

  "146": [["Birinchi darslar yopiq maydonchalarda yoki avtodromlarda.", "Umumiy yo'llarda emas.", "Avval boshqarishni o'rganing, keyin oqimga chiqing."], "Bo'sh maydonchada ilashish va tormozlashni mashq qilasiz."],
  "147": [["Yo'llarda o'rgatish faqat instruktor bilan.", "O'rganuvchi dastlabki ko'nikmaga ega bo'lishi kerak.", "O'rganuvchi Qoidalarni bilishi va amal qilishi shart."], "Instruktor bilan shahar ko'chalarida haydaysiz."],
  "149": [["«A»: 16 yosh. «B» va «C»: 18 yosh.", "«BE» va «CE»: 19 yosh.", "«D», «DE», tramvay va trolleybus: 21 yosh."], "17 yoshda «B» toifasidagi o'qishni hali tugata olmaysiz."],
  "150": [["Old va orqada o'quv belgisi.", "O'rgatuvchi uchun ilashish va tormozning qo'shimcha tepkilari, qo'shimcha ko'zgu va GPS.", "Yo'nalishlar DYHXX bilan kelishiladi."], "Instruktor yo'lovchi o'rindig'idan tormozlay oladi."],

  "157": [["Xavfsizlik choralari, chiqish, tushish va joylashish tartibini tushuntiring.", "Yo'lovchilarni xavfsiz tashish mumkinligiga ishonch hosil qiling.", "Eshik va kamarlarni tekshiring."], "Safardan oldin aytasiz: kamar taqildi, eshiklar yopildi."],
  "158": [["Yo'lovchilar faqat transport to'liq to'xtagach chiqadi va tushadi.", "Eshiklar yopilgach yuring.", "To'liq to'xtamaguncha eshikni ochmang."], "Avtobus yurishdan oldin eshiklarini yopadi."],
  "159": [["Kabinadan tashqarida (maxsus yuk mashinalaridan tashqari), tirkama va yuk ustida odam tashish taqiqlanadi.", "Bolalarni yuk mashinasi yukxonasida va mo'ljaldan ko'p odamni tashish taqiqlanadi.", "12 yoshgacha bolalarni mototsikl orqa o'rindig'ida va bolalar qurilmasiz old o'rindiqda tashish taqiqlanadi."], "7 yoshgacha bola bolalar o'rindig'ida, 7 dan 12 gacha kamarli ushlab turuvchi qurilmada tashiladi."],

  "161": [["Harakatdan oldin yukning joylashuvi va mahkamlanganini tekshiring.", "Yo'lda uni kuzatib boring.", "U tushib ketmasin va haydashga xalaqit bermasin."], "10 km dan keyin to'xtab, tasmalarni qayta tortasiz."],
  "162": [["Yuk ko'rishni cheklamasin va boshqarishni qiyinlashtirmasin.", "U chiroqlar, raqamlar va qo'l ishoralarini to'smasin.", "Yengil mashina tomidagi yuk balandligi 1 m, gabaritdan chiqishi 0,5 m dan oshmasin."], "Tomdagi velosipedlar maxsus mahkamlagichlar bilan tutiladi."],
  "163": [["Oldi yoki orqasi tomonga 1 m dan, yon tomonga 0,4 m dan ortiq chiqqan yuk belgi bilan belgilanadi.", "Qorong'ida oldiga oq chiroq yoki qaytargich, orqasiga qizil qo'shiladi.", "Belgisiz bu qoidabuzarlik."], "Uzun quvur furgondan 1,5 m chiqib turibdi: belgini qo'yasiz."],
  "164": [["Eni 2,55 m dan (refrijeratorlar 2,6 m) yoki balandligi 4 m dan ortiq.", "Uzunligi yakka transport uchun 12 m, tarkib uchun 20 m dan ortiq yoki yuk 2 m dan ko'p chiqib turgan.", "Harakat DYHXX bilan kelishilishi shart."], "4,2 m balandlikdagi yuk uchun DYHXX bilan kelishilgan yo'nalish kerak."],

  "165": [["Velosiped va individual harakatlanish vositasini boshqarish, arava haydash va hayvon haydash 14 yoshdan.", "Moped, skuter va kichik hajmdagi mototransport 16 yoshdan.", "Kichik bolalar umumiy yo'llarda buni qila olmaydi."], "13 yoshli bola qatnov qismida velosipedda yura olmaydi."],
  "166": [["Chetki o'ng tasmada, iloji boricha o'ngda, bir qatorda yuring.", "Piyodalarga xalaqit bermasa yo'l yoqasidan mumkin.", "Guruhlar quvib o'tish oson bo'lishi uchun bo'linadi."], "O'n besh kishilik velosipedchilar guruhi kichik guruhlarga bo'linadi."],
  "167": [["Tovushli ishora va soz tormoz.", "Qorong'ida old tomonda oq chiroq yoki qaytargich, orqada qizil, yonlarda zarg'aldoq yoki qizil.", "Velosiped yo'lkasiz qatnov qismida qorong'ida nur qaytaruvchi kiyim."], "Kechki sayr: old chiroq, qizil orqa chiroq, nur qaytaruvchi jilet."],
  "168": [["Rulni ushlamasdan yoki bir qo'lda (ishoradan tashqari) yurish taqiqlanadi.", "Odam tashish (maxsus o'rindiqda 7 yoshgacha bola mumkin) va katta yuk tashish taqiqlanadi.", "Velosiped yo'lkasi bo'lsa qatnov qismidan yurmang. Kesib o'tishda velosipedni yetaklang."], "«Zebra»dan velosipedni yetaklab o'tasiz."],
  "169": [["Chorrahadan tashqaridagi tartibga solinmagan velosiped yo'lkasi kesishuvida velosipedchilar yo'ldagi transportga yo'l beradi.", "Velosiped yo'lkasi trotuarni kesib o'tsa, velosipedchi piyodaga yo'l beradi.", "Svetoforda velosipedchilar velosiped ishorasiga amal qiladi."], "Velosiped yo'lkasi trotuarni kesadi: piyodani o'tkazasiz."],
  "pmd122": [["Elektrosamokat va shunga o'xshash vositalar haydovchilari Qoidalarga qat'iy rioya qiladi.", "Trotuar, yo'lka va velosiped yo'lkalarida 10 km/soatgacha.", "Ular bo'lmasa, yo'lning o'ng chetida 20 km/soatgacha."], "Trotuarda odimlab yurasiz."],
  "pmd123": [["Piyodalarga xavf tug'dirsangiz, tushing yoki tezlikni odim tezligigacha kamaytiring.", "Oqimlar birlashgan joyda piyodalar doim ustun.", "Velosiped tasmalarida individual vositalar haydovchilari boshqa mexanik transportdan ustun."], "Piyoda birgalikdagi yo'lkaga chiqdi: to'xtaysiz."],

  "176": [["Staji 2 yildan kam haydovchilar orqada qora «!» tushirilgan sariq kvadrat qo'yadi.", "Bolalar guruhi tashilganda old va orqada «Bolalarni tashish» belgisi.", "«Shifokor» va «Nogiron» kabi boshqa belgilar xohishga ko'ra."], "Imtihondan ikki oy o'tib orqa oynaga sariq kvadratni qo'yasiz."],

  "m1.1": [["Qarama-qarshi oqimlarni ajratadi, xavfli joylar va to'xtab turish chegarasini bildiradi.", "Qatnov qismi chetini ham bildiradi, u yerda kesib o'tish mumkin.", "Boshqa joyda kesib o'tish taqiqlanadi."], "To'xtab turgan mashinani aylanib o'tishda sidirg'a chiziqqa tegmaysiz, kutasiz."],
  "m1.3": [["To'rt va undan ortiq tasmali yo'llarda qarama-qarshi oqimlarni ajratadi.", "Uni kesib o'tib bo'lmaydi.", "Quvib o'tishni o'z yo'nalishingiz ichida ushlab turadi."], "Olti tasmali prospektda qarama-qarshi tasmalarga hech qachon chiqmaysiz."],
  "m1.4": [["Chekka yoki yo'l chetidagi to'siq ustidagi sariq chiziq.", "To'xtashni taqiqlaydi, yakka yoki belgi bilan.", "Istisno: tezkor xizmatlar va maxsus bo'yalgan xizmat mashinalari."], "Yo'l chetida sariq chiziq: bir soniya ham to'xtamaysiz."],
  "m1.5": [["Ikki yoki uch tasmali yo'llarda qarama-qarshi oqimlarni ajratadi.", "Shuningdek bir yo'nalishdagi tasmalarni.", "Uni istalgan tomondan kesib o'tish mumkin."], "Yo'l bo'sh bo'lganda quvib o'tish uchun uzuq chiziqni kesasiz."],
  "m1.9": [["Reversiv tasmalarni belgilaydi.", "Reversiv svetofor o'chiq bo'lsa, chiziq o'ng tomoningizda bo'lsagina kesib o'ting.", "Svetofor o'chsa, darhol chiziqdan o'ngga o'ting."], "Qizil X o'chdi: 1.9 chiziqdan o'ngga o'tasiz."],
  "m1.10": [["To'xtab turishni taqiqlovchi sariq chiziq.", "Yakka yoki to'xtab turish taqiqlangan belgi bilan.", "Chekka yoki to'siq ustiga chiziladi."], "Yonida qisqa to'xtash mumkin, to'xtab turish mumkin emas."],
  "m1.11": [["Qayta tizilish faqat bir tomondan ruxsat etilgan joyda oqimlarni ajratadi.", "Uzuq tomondan kesib o'tish mumkin.", "Sidirg'a tomondan faqat quvib yoki aylanib o'tishni tugatish uchun."], "Quvib o'tgandan keyin boshqa yo'li yo'qligi uchun sidirg'a tomondan qaytib kesib o'tasiz."],
  "m1.12": [["To'xtash chizig'i.", "«To'xtang» belgisi yoki svetofor yoxud tartibga soluvchining taqiqlovchi ishorasida.", "Transportning old qismi uni kesib o'tmasligi kerak."], "Qizilda old g'ildiraklar chiziq orqasida to'xtaydi."],
  "m1.14": [["Oq «zebra» 1.14.1 va oq-sariq 1.14.2 piyodalar o'tish joyini bildiradi.", "1.14.3 strelkalar yurish yo'nalishini, 1.14.4 qizil-oq chiziqlar maktab oldidagi o'tish joyini bildiradi.", "Baland o'tish joylari 1.29 ham o'tish joyini bildiradi."], "Maktab yonida qizil-oq o'tish joyida bolalarni kuzatasiz."],
  "m-conflict": [["Belgilar chiziqlardan ustun.", "Vaqtinchalik belgi va chiziqlar doimiylardan ustun.", "Ko'rinmaydigan chiziqlar, masalan qor ostida, belgilar bilan almashtiriladi."], "Yo'l ishlarida sariq vaqtinchalik chiziqlarga amal qilasiz."],

  "t-tyre": [["Yengil mashinalar, furgonlar va yengil tirkamalar uchun 1,6 mm.", "Og'ir yuk mashinalari va tirkamalar uchun 1,0 mm, avtobuslar 2,0 mm, mototsikllar 0,8 mm.", "Ko'rinib turgan kord, kesilish va shishlar ham foydalanishni taqiqlaydi."], "Protektorni o'lchab, eskirgan shinalarni almashtirasiz."],
  "t-kit": [["Yengil va yuk mashinalari va g'ildirakli traktorlar: tibbiyot qutichasi, o't o'chirgich, to'xtash belgisi yoki miltillovchi qizil chiroq, nur qaytargichli jilet.", "Avtobuslarda yana ikkita o't o'chirgich va bolg'acha.", "Hammasi joyida va soz ekanini tekshiring."], "Tibbiyot qutichasining yaroqlilik muddatini har yili tekshirasiz."],
  "t-glass": [["Old va yon oynalar kamida 70 foiz yorug'lik o'tkazishi kerak.", "Istisno: lyuklar va ruxsatnoma bilan qoraytirilgan oynalar.", "Tashqi ko'zgulari bor mashinalarning orqa oynalarini qoraytirish mumkin."], "Old oynalarni qoraytirish uchun ruxsatnoma kerak."],
};

